238: - name: Normalize kernel param adds
239:   ansible.builtin.set_fact:
240:     common_kernel_params_add_deduped: >-
241:       {%- set ns = namespace(result=[]) -%}
242:       {%- for token in common_kernel_params_add_merged -%}
243:         {%- set key = token | regex_replace('=.*$', '') -%}
244:         {%- set filtered = [] -%}
245:         {%- for existing in ns.result -%}
246:           {%- set existing_key = existing | regex_replace('=.*$', '') -%}
247:           {%- if existing_key != key -%}
248:             {%- set _ = filtered.append(existing) -%}
249:           {%- endif -%}
250:         {%- endfor -%}
251:         {%- set ns.result = filtered -%}
252:         {%- set _ = ns.result.append(token) -%}
253:       {%- endfor -%}
254:       {{ ns.result }}
255:   when: common_kernel_params_all | length > 0
256: 
257: - name: Build kernel parameter keys
258:   ansible.builtin.set_fact:
259:     common_kernel_params_remove_keys: >-
260:       {{ common_kernel_params_remove_merged
261:          | map('regex_replace', '=.*$', '')
262:          | list }}
263:     common_kernel_params_add_keys: >-
264:       {{ common_kernel_params_add_deduped
