278:     common_kernel_params_remove_needed: >-
279:       {%- set to_remove = [] -%}
280:       {%- set current_keys = common_kernel_params_current_keys -%}
281:       {%- set add_needed_keys = (common_kernel_params_add_deduped
282:           | difference(common_kernel_params_current_intersection)
283:           | map('regex_replace', '=.*$', '')
284:           | list) -%}
285:       {%- set remove_keys = common_kernel_params_remove_keys + add_needed_keys -%}
286:       {%- for key in remove_keys -%}
287:         {%- if key in current_keys -%}
288:           {%- if key not in to_remove -%}
289:             {%- set _ = to_remove.append(key) -%}
290:           {%- endif -%}
291:         {%- endif -%}
292:       {%- endfor -%}
293:       {{ to_remove }}
294:   when: common_kernel_params_all | length > 0
