 5: - name: Run OpenSCAP ANSSI BP28 High remediation
 6:   ansible.builtin.command:
 7:     cmd: >
 8:       oscap xccdf eval
 9:       {% if configure_hardening_oscap_apply_remediation %}
10:       --remediate
11:       {% endif %}
12:       --fetch-remote-resources
13:       --results {{ configure_hardening_oscap_results_dir }}/oscap-results.xml
14:       --report {{ configure_hardening_oscap_results_dir }}/oscap-report.html
15:       --profile {{ configure_hardening_oscap_profile }}
16:       {% if configure_hardening_oscap_tailoring_file is defined %}
17:       --tailoring-file {{ configure_hardening_oscap_tailoring_file }}
18:       {% endif %}
19:       {{ configure_hardening_oscap_ds_file }}
20:   register: configure_hardening_oscap_remediation
21:   failed_when: configure_hardening_oscap_remediation.rc not in [0, 2]
22:   changed_when: configure_hardening_oscap_remediation.rc == 2
23:   when:
24:     - revert is not defined or not revert
25:     - configure_hardening_oscap_ds_file is defined
26:     - configure_hardening_oscap_profile is defined

